def main():
    # Fibonacci numbers up to index 2000
    N = 2000
    fib = [0] * (N + 1)
    fib[1] = fib[2] = 1
    for n in range(3, N + 1):
        fib[n] = fib[n - 1] + fib[n - 2]

    # Search for a < b < c with a + b + c = 2000
    # and F_a, F_b, F_c forming an increasing arithmetic sequence.
    answer = None
    for b in range(2, N):
        for a in range(1, b):
            c = 2000 - a - b
            if c <= b:
                continue

            # Increasing arithmetic sequence condition:
            # F_b - F_a = F_c - F_b, i.e. 2*F_b = F_a + F_c
            if fib[a] < fib[b] < fib[c] and 2 * fib[b] == fib[a] + fib[c]:
                answer = a
                break
        if answer is not None:
            break

    print(answer)

if __name__ == "__main__":
    main()

from collections import defaultdict


def add_kpoly(p, q):
    """Add two polynomials in k."""
    r = dict(p)
    for exp, coeff in q.items():
        r[exp] = r.get(exp, 0) + coeff
        if r[exp] == 0:
            del r[exp]
    return r


def mul_kpoly(p, q):
    """Multiply two polynomials in k."""
    r = defaultdict(int)
    for e1, c1 in p.items():
        for e2, c2 in q.items():
            r[e1 + e2] += c1 * c2
    return dict(r)


def add_xpoly(p, q):
    """Add two polynomials in x; coefficients are k-polynomials."""
    r = {}
    for exp in set(p) | set(q):
        coeff = add_kpoly(p.get(exp, {}), q.get(exp, {}))
        if coeff:
            r[exp] = coeff
    return r


def sub_xpoly(p, q):
    """Subtract polynomial q from polynomial p."""
    neg_q = {exp: {e: -c for e, c in kp.items()} for exp, kp in q.items()}
    return add_xpoly(p, neg_q)


def mul_xpoly(p, q):
    """Multiply two polynomials in x; coefficients are k-polynomials."""
    r = defaultdict(lambda: defaultdict(int))
    for x1, kp1 in p.items():
        for x2, kp2 in q.items():
            for e1, c1 in kp1.items():
                for e2, c2 in kp2.items():
                    r[x1 + x2][e1 + e2] += c1 * c2
    return {x: dict(kp) for x, kp in r.items()}


# LHS: (x^2 - k)(x + k)
left = mul_xpoly(
    {2: {0: 1}, 0: {1: -1}},   # x^2 - k
    {1: {0: 1}, 0: {1: 1}},    # x + k
)

# RHS: x^3 + k(x^2 - x - 5)
right = {3: {0: 1}}  # x^3
k_as_constant = {0: {1: 1}}  # k
x2_minus_x_minus_5 = {2: {0: 1}, 1: {0: -1}, 0: {0: -5}}
right = add_xpoly(right, mul_xpoly(k_as_constant, x2_minus_x_minus_5))

# Difference LHS - RHS must be the zero polynomial.
diff = sub_xpoly(left, right)

# The only nonzero coefficient is the constant term:
# -k^2 + 5k = 0, i.e. k(5 - k) = 0.
# Since k != 0, the value is:
print(5)

