def divisor_sum(n):
    """Return the sum of all positive divisors of n."""
    if n == 1:
        return 1
    total = 0
    d = 1
    while d * d <= n:
        if n % d == 0:
            total += d
            if d * d != n:
                total += n // d
        d += 1
    return total

def is_prime(n):
    """Return True if n is prime."""
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True

def count_superdeficient():
    # Let m = f(n). If f(f(n)) = n+2, then
    # n+2 = f(m) >= m+1 = f(n)+1 >= n+2.
    # Therefore equality holds throughout, so n is prime and n+1 is prime.
    # The only consecutive primes are 2 and 3, so only n=2 is possible.
    if is_prime(2) and is_prime(3):
        n = 2
        if divisor_sum(divisor_sum(n)) == n + 2:
            return 1
    return 0

