from collections import defaultdict


def poly_add(p, q):
    r = defaultdict(int)
    for key, value in p.items():
        r[key] += value
    for key, value in q.items():
        r[key] += value
    return {key: value for key, value in r.items() if value}


def poly_mul(p, q):
    r = defaultdict(int)
    for (ea, eb), ca in p.items():
        for (fa, fb), cb in q.items():
            r[(ea + fa, eb + fb)] += ca * cb
    return {key: value for key, value in r.items() if value}


def mono(pa, pb, coeff=1):
    return {(pa, pb): coeff}


# With c = -a - b, all three denominators are the same:
