solutions = []

# Case 1: a < 0, so f(a) = a^2 - 2
if target + 2 >= 0:
    root = math.isqrt(target + 2)
    for a in (root, -root):
        if a < 0 and f(a) == target:
            solutions.append(a)

# Case 2: a >= 0, so f(a) = 2a - 20
