import math

def sum_of_positive_divisors(n):
    total = 0
    for divisor in range(1, math.isqrt(n) + 1):
        if n % divisor == 0:
            total += divisor
            counterpart = n // divisor
            if counterpart != divisor:
                total += counterpart
    return total

def count_distinct_prime_factors(x):
    count = 0

    if x % 2 == 0:
        count += 1
        while x % 2 == 0:
            x //= 2

    factor = 3
    while factor * factor <= x:
        if x % factor == 0:
            count += 1
            while x % factor == 0:
                x //= factor
        factor += 2

    if x > 1:
        count += 1

    return count

