N = 10
COLORS = ('B', 'R', 'G', 'O')
COUNTS = (5, 2, 2, 1)


def generate_colorings(counts, prefix):
    """Generate every linear color arrangement exactly once."""
    if len(prefix) == N:
        yield prefix
        return

    for i, color in enumerate(COLORS):
        if counts[i] > 0:
            counts[i] -= 1
            yield from generate_colorings(counts, prefix + (color,))
            counts[i] += 1


def has_no_adjacent_greens(arr):
    """Return True if the two green plates are not adjacent on the circle."""
    for i in range(N):
        if arr[i] == 'G' and arr[(i + 1) % N] == 'G':
            return False
    return True


def is_fixed_by_rotation(arr, shift):
    """Return True if arr is unchanged by rotating by `shift` positions."""
    for i in range(N):
        if arr[i] != arr[(i + shift) % N]:
            return False
    return True


fixed_counts = [0] * N

for coloring in generate_colorings(list(COUNTS), ()):
    if not has_no_adjacent_greens(coloring):
        continue

    for shift in range(N):
        if is_fixed_by_rotation(coloring, shift):
            fixed_counts[shift] += 1

answer = sum(fixed_counts) // N
print(answer)

import math

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    for d in range(3, math.isqrt(n) + 1, 2):
        if n % d == 0:
            return False
    return True

def solve() -> None:
    # 120 = 8 * 3 * 5
    # For a prime p > 5:
    #   p is odd, so p^2 ≡ 1 (mod 8)
    #   p is not divisible by 3, so p^2 ≡ 1 (mod 3)
    #   p is not divisible by 5, so p^2 ≡ 1 or 4 (mod 5)
    allowed_mod8 = {1}
    allowed_mod3 = {1}
    allowed_mod5 = {1, 4}

    # Find all remainders modulo 120 that satisfy all three conditions.
    possible = set()
    for r in range(120):
        if (r % 8 in allowed_mod8 and
            r % 3 in allowed_mod3 and
            r % 5 in allowed_mod5):
            possible.add(r)

    # Verify that each possible remainder is actually attained by some prime > 5.
    attained = set()
    p = 7
    while attained != possible:
        if is_prime(p):
            attained.add((p * p) % 120)
        p += 1

    print(len(possible))

if __name__ == "__main__":
    solve()

import math
from fractions import Fraction


# Represent a number a + b*sqrt(3) as a tuple (a, b) of Fractions.
def q_add(x, y):
    return (x[0] + y[0], x[1] + y[1])

def q_sub(x, y):
    return (x[0] - y[0], x[1] - y[1])

def q_mul(x, y):
    # (a+b√3)(c+d√3) = (ac+3bd) + (ad+bc)√3
    return (x[0] * y[0] + 3 * x[1] * y[1],
            x[0] * y[1] + x[1] * y[0])

def q_scale(k, x):
    return (k * x[0], k * x[1])

def q_sign(x):
    """Return 1, -1, or 0 for a + b√3."""
    a, b = x
    if a == 0 and b == 0:
        return 0
    if b == 0:
        return 1 if a > 0 else -1
    if a == 0:
        return 1 if b > 0 else -1
    if a * b > 0:
        return 1 if a > 0 else -1
    # a and b have opposite signs.
    # Compare a^2 with 3*b^2.
    cmp = a * a - 3 * b * b
    if a > 0:          # a > 0, b < 0: positive iff a^2 > 3b^2
        return 1 if cmp > 0 else -1
    else:              # a < 0, b > 0: positive iff 3b^2 > a^2
        return -1 if cmp > 0 else 1


# Vector as (x, y), where each coordinate is a Q(√3) number.
def v_add(u, v):
    return (q_add(u[0], v[0]), q_add(u[1], v[1]))

def v_sub(u, v):
    return (q_sub(u[0], v[0]), q_sub(u[1], v[1]))

def v_scale(k, u):
    return (q_scale(k, u[0]), q_scale(k, u[1]))

def v_cross(u, v):
    # u.x * v.y - u.y * v.x
    return q_sub(q_mul(u[0], v[1]), q_mul(u[1], v[0]))


# Place B at origin.
# A = (3, 0)
A = ((Fraction(3), Fraction(0)), (Fraction(0), Fraction(0)))

# C = (5 cos 120°, 5 sin 120°) = (-5/2, (5√3)/2)
C = ((Fraction(-5, 2), Fraction(0)),
     (Fraction(0), Fraction(5, 2)))

B = ((Fraction(0), Fraction(0)), (Fraction(0), Fraction(0)))

# |AC| = 7 by the law of cosines:
# AC^2 = 3^2 + 5^2 - 2*3*5*cos(120°) = 49.
AC_length = Fraction(7)

# DE = |1+t| * AC_length = 15, so t = -1 ± 15/7.
t_candidates = [Fraction(8, 7), Fraction(-22, 7)]


def is_convex_pentagon(t):
    # D = A - t*C, E = C - t*A
    D = v_sub(A, v_scale(t, C))
    E = v_sub(C, v_scale(t, A))

    edges = [
        v_sub(B, A),  # AB
        v_sub(C, B),  # BC
        v_sub(D, C),  # CD
        v_sub(E, D),  # DE
        v_sub(A, E),  # EA
    ]

    signs = []
    for i in range(5):
        cross = v_cross(edges[i], edges[(i + 1) % 5])
        s = q_sign(cross)
        if s == 0:
            return False
        signs.append(s)

    return all(s == signs[0] for s in signs)


