            result[exp1 + exp2] += coef1 * coef2
    return dict(result)

def add_polys(p, q):
    result = defaultdict(int)
    for exp, coef in p.items():
        result[exp] += coef
    for exp, coef in q.items():
        result[exp] += coef
    return dict(result)

