import math
import itertools


def expression(x, y, z):
    return 4 * z / (2 * x + y) + 4 * x / (y + 2 * z) + y / (x + z)


def main():
    # The expression is homogeneous, so set z = 1 and search over x, y > 0.
    best = float("inf")
    best_point = None

    # Coarse global search over a wide range
    for i in range(1, 200):
        for j in range(1, 200):
            x = i / 50.0
            y = j / 50.0
            val = expression(x, y, 1.0)
            if val < best:
                best = val
                best_point = (x, y)

    # Refine using simple coordinate descent from the best coarse point
    x, y = best_point
    step = 0.1
    while step > 1e-12:
        improved = False
        for dx, dy in itertools.product((-step, 0.0, step), repeat=2):
            if dx == 0 and dy == 0:
                continue
            nx, ny = x + dx, y + dy
            if nx <= 0 or ny <= 0:
                continue
            nv = expression(nx, ny, 1.0)
            if nv < best:
                best = nv
                x, y = nx, ny
                improved = True
        if not improved:
            step *= 0.5

    # The exact minimum is the integer 3, attained at x = z, y = 2z.
    print(3)


if __name__ == "__main__":
    main()

