import math

def count_positive_ordered_pairs(n):
    # D(n) = (# divisors of n congruent to 1 mod 4) - (# divisors congruent to 3 mod 4)
    divisor_balance = 0

    for d in range(1, math.isqrt(n) + 1):
        if n % d == 0:
            if d == n // d:
                divisors = (d,)
            else:
                divisors = (d, n // d)

            for div in divisors:
                r = div % 4
                if r == 1:
                    divisor_balance += 1
                elif r == 3:
                    divisor_balance -= 1
                # r == 0 or 2 contributes 0

    # f(n) = D(n) - 1 if n is a perfect square, otherwise D(n)
    is_perfect_square = (math.isqrt(n) ** 2 == n)
    return divisor_balance - (1 if is_perfect_square else 0)

n = 1
while count_positive_ordered_pairs(n) != 3:
    n += 1

print(n)

