def face_index(axis, sign):
    """axis: 0=x, 1=y, 2=z。sign: 1=正方向, -1=負方向。"""
    if axis == 0:
        return 0 if sign == 1 else 1
    if axis == 1:
        return 2 if sign == 1 else 3
    return 4 if sign == 1 else 5

def vertex_sum(assignment):
    """8つの頂点について、その頂点を含む3面の数の積の総和を求める。"""
    total = 0
    for sx, sy, sz in vertices:
        product = 1
        product *= assignment[face_index(0, sx)]
        product *= assignment[face_index(1, sy)]
        product *= assignment[face_index(2, sz)]
        total += product
    return total

