from fractions import Fraction

# We use shifted variable y = x - r.
# Then f has known roots y=1, y=7 and unknown third root y=u.
# g has known roots y=3, y=9 and unknown third root y=v.
#
# Expressions are represented as (constant, coefficient of u, coefficient of v).

def expr_const(c):
    return (Fraction(c), Fraction(0), Fraction(0))

def expr_u():
    # Represents -u, coming from (y - u)
    return (Fraction(0), Fraction(-1), Fraction(0))

def expr_v():
    # Represents -v, coming from (y - v)
    return (Fraction(0), Fraction(0), Fraction(-1))

def expr_add(e1, e2):
    return (e1[0] + e2[0], e1[1] + e2[1], e1[2] + e2[2])

def expr_neg(e):
    return (-e[0], -e[1], -e[2])

def expr_mul(e1, e2):
    # Only multiplication by a constant expression occurs in this expansion.
    if e1[1] == 0 and e1[2] == 0:
        return (e2[0] * e1[0], e2[1] * e1[0], e2[2] * e1[0])
    if e2[1] == 0 and e2[2] == 0:
        return (e1[0] * e2[0], e1[1] * e2[0], e1[2] * e2[0])
    raise ValueError("Nonlinear term appeared")

def poly_mul(p, q):
    # Multiply two polynomials whose coefficients are expressions.
    res = [expr_const(0) for _ in range(len(p) + len(q) - 1)]
    for i, a in enumerate(p):
        for j, b in enumerate(q):
            res[i + j] = expr_add(res[i + j], expr_mul(a, b))
    return res

# (y - 1)(y - 7)
f_base = poly_mul([expr_const(-1), expr_const(1)],
                  [expr_const(-7), expr_const(1)])
# Multiply by (y - u)
f_coeffs = poly_mul(f_base, [expr_u(), expr_const(1)])

# (y - 3)(y - 9)
g_base = poly_mul([expr_const(-3), expr_const(1)],
                  [expr_const(-9), expr_const(1)])
# Multiply by (y - v)
g_coeffs = poly_mul(g_base, [expr_v(), expr_const(1)])

# f(y) - g(y) must be the constant r.
diff = [expr_add(f_coeffs[i], expr_neg(g_coeffs[i])) for i in range(4)]

# The y^2 and y coefficients must be 0.
# diff[2] gives: constant + coeff_u*u + coeff_v*v = 0
a1, b1, c1 = diff[2][1], diff[2][2], -diff[2][0]
# diff[1] gives: constant + coeff_u*u + coeff_v*v = 0
a2, b2, c2 = diff[1][1], diff[1][2], -diff[1][0]

# Solve the 2x2 linear system:
# a1*u + b1*v = c1
# a2*u + b2*v = c2
det = a1 * b2 - a2 * b1
u = (c1 * b2 - c2 * b1) / det
v = (a1 * c2 - a2 * c1) / det

# r is the constant term of f(y) - g(y).
r = diff[0][0] + diff[0][1] * u + diff[0][2] * v

print(int(r))

