import math

def is_prime(n: int) -> bool:
    """Return True if n is a prime number."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for d in range(3, math.isqrt(n) + 1, 2):
        if n % d == 0:
            return False
    return True

# 6x^2 - 47x + 15 = (3x - 1)(2x - 15)
# For |(3x - 1)(2x - 15)| to be prime, one factor must be ±1.

