# Solve 3x - 1 = 1  -> x = 2/3, not integer
# Solve 3x - 1 = -1 -> x = 0
if abs(3 * 0 - 1) == 1:
    candidate_x_values.append(0)

# Solve 2x - 15 = 1  -> x = 8
if abs(2 * 8 - 15) == 1:
    candidate_x_values.append(8)

# Solve 2x - 15 = -1 -> x = 7
if abs(2 * 7 - 15) == 1:
    candidate_x_values.append(7)

valid_x_values = []
for x in candidate_x_values:
    value = abs((3 * x - 1) * (2 * x - 15))
    if is_prime(value):
        valid_x_values.append(x)

print(max(valid_x_values))

