import math


def factorizations(rem, min_factor=2):
    """Return factorizations of rem into integers >= min_factor, nondecreasing."""
    results = []
    for f in range(min_factor, rem + 1):
        if rem % f == 0:
            if f == rem:
                results.append((f,))
            else:
                for tail in factorizations(rem // f, f):
                    results.append((f,) + tail)
    return results


def divisor_count(n, primes):
    """Compute the number of positive divisors of n."""
    count = 1
    for p in primes:
        if p * p > n:
            break
        if n % p == 0:
            exp = 0
            while n % p == 0:
                n //= p
                exp += 1
            count *= exp + 1
    if n > 1:
        count *= 2
    return count


