import math

# Polynomial x^5 - x^2 - x - 1, coefficients from highest degree to constant
poly = [1, 0, 0, -1, -1, -1]

def eval_poly(coeffs, x):
    result = 0
    for c in coeffs:
        result = result * x + c
    return result

def divide_poly(dividend, divisor):
    """Return quotient if divisor exactly divides dividend, else None."""
    if len(dividend) < len(divisor):
        return None
    quotient_degree = len(dividend) - len(divisor)
    quotient = [0] * (quotient_degree + 1)
    remainder = dividend[:]

    for i in range(quotient_degree + 1):
        if remainder[i] % divisor[0] != 0:
            return None
        coeff = remainder[i] // divisor[0]
        quotient[i] = coeff
        for j in range(len(divisor)):
            remainder[i + j] -= coeff * divisor[j]

    if any(remainder):
        return None
    return quotient

def integer_divisors(n):
    n = abs(n)
    divs = set()
    for d in range(1, int(math.isqrt(n)) + 1):
        if n % d == 0:
            divs.add(d)
            divs.add(n // d)
    return divs

# Mignotte-style coefficient bound for a monic factor
bound = 2 ** len(poly) * math.sqrt(sum(c * c for c in poly)) + 10
bound = int(bound)

factors = []

# Look for linear factors: possible rational roots are divisors of the constant term
constant = poly[-1]
for root in integer_divisors(constant):
    for sign in (1, -1):
        r = sign * root
        if eval_poly(poly, r) == 0:
            factors.append([1, -r])
            poly = divide_poly(poly, [1, -r])

# Look for a quadratic factor x^2 + a x + b
# The constant b must divide the polynomial's constant term.
for b in integer_divisors(constant):
    for sign in (1, -1):
        b_val = sign * b
        for a in range(-bound, bound + 1):
            quadratic = [1, a, b_val]
            quotient = divide_poly(poly, quadratic)
            if quotient is not None:
                factors.append(quadratic)
                poly = quotient
                break
        else:
            continue
        break

# If no nontrivial factor was found, the whole remaining polynomial is irreducible
if len(factors) == 0:
    factors.append(poly)

answer = sum(eval_poly(f, 2) for f in factors)
print(answer)

