from fractions import Fraction
from itertools import combinations


class Sqrt3:
    """数 a + b√3 を正確に表すクラス."""
    __slots__ = ("a", "b")

    def __init__(self, a, b=0):
        self.a = Fraction(a)
        self.b = Fraction(b)

    def __add__(self, other):
        if isinstance(other, Sqrt3):
            return Sqrt3(self.a + other.a, self.b + other.b)
        return Sqrt3(self.a + Fraction(other), self.b)

    def __radd__(self, other):
        return self.__add__(other)

    def __sub__(self, other):
        if isinstance(other, Sqrt3):
            return Sqrt3(self.a - other.a, self.b - other.b)
        return Sqrt3(self.a - Fraction(other), self.b)

    def __rsub__(self, other):
        return Sqrt3(Fraction(other) - self.a, -self.b)

    def __neg__(self):
        return Sqrt3(-self.a, -self.b)

    def __mul__(self, other):
        return Sqrt3(self.a * Fraction(other), self.b * Fraction(other))

    def __rmul__(self, other):
        return self.__mul__(other)

    def __eq__(self, other):
        if isinstance(other, Sqrt3):
            return self.a == other.a and self.b == other.b
        return self.b == 0 and self.a == Fraction(other)

    def __hash__(self):
        return hash((self.a, self.b))

    def __repr__(self):
        return f"({self.a}+{self.b}√3)"


