def add(p, q):
    return (p[0] + q[0], p[1] + q[1])


def sub(p, q):
    return (p[0] - q[0], p[1] - q[1])


def mul(p, k):
    return (p[0] * k, p[1] * k)


def rot90(p):
    """反時計回りに90度回転させる: (x, y) -> (-y, x)"""
    return (-p[1], p[0])


def squares_from_two_vertices(p, q):
    """p, q を頂点として持つ正方形を全て返す."""
    squares = []
    v = sub(q, p)

    # p, q が辺の両端の場合: 2通り
    for r in (rot90(v), -rot90(v)):
        square = frozenset({p, q, add(p, r), add(q, r)})
        squares.append(square)

    # p, q が対角線の両端の場合: 1通り
    center = mul(add(p, q), Fraction(1, 2))
    half_diag = mul(v, Fraction(1, 2))
    rotated_half_diag = rot90(half_diag)
    square = frozenset({
        p,
        q,
        add(center, rotated_half_diag),
        sub(center, rotated_half_diag),
    })
    squares.append(square)

    return squares


