# 10! = 3628800
N = math.factorial(10)

# Factorize N into prime powers
def factorize(n):
    factors = {}
    p = 2
    while p * p <= n:
        while n % p == 0:
            factors[p] = factors.get(p, 0) + 1
            n //= p
        p += 1
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors

prime_factors = factorize(N)  # {2: 8, 3: 4, 5: 2, 7: 1}

# Generate all ways to split a prime exponent among 4 numbers
def exponent_partitions(total, parts):
    if parts == 1:
        yield (total,)
    else:
        for first in range(total + 1):
            for rest in exponent_partitions(total - first, parts - 1):
                yield (first,) + rest

# For each prime, store tuples of (p^exp_a, p^exp_b, p^exp_c, p^exp_d)
prime_options = []
for prime, exponent in prime_factors.items():
    options = []
    for exps in exponent_partitions(exponent, 4):
        options.append(tuple(prime ** e for e in exps))
    prime_options.append(options)

best_sum = None

# Combine prime contributions to form a, b, c, d
for p2, p3, p5, p7 in product(*prime_options):
    vals = [
        p2[i] * p3[i] * p5[i] * p7[i]
        for i in range(4)
    ]
