from fractions import Fraction
from functools import lru_cache

@lru_cache(maxsize=None)
def f(x: int) -> Fraction:
    """Return f(x) using f(a) + f(b) = n^2 when a + b = 2^n."""
    if x == 1:
        # 1 + 1 = 2 = 2^1, so 2*f(1) = 1
        return Fraction(1, 2)

    # Smallest power of 2 strictly greater than x
    p = 1 << x.bit_length()      # p = 2^n
    n = p.bit_length() - 1

    # If x is itself a power of 2, then p = 2*x and the partner is x itself
    if p == 2 * x:
        return Fraction(n * n, 2)

    # Otherwise the partner is p - x, and p - x < x
    return n * n - f(p - x)

