def poly_add(p, q):
    result = dict(p)
    for degree, coeff in q.items():
        result[degree] = result.get(degree, 0) + coeff
    return {degree: coeff for degree, coeff in result.items() if coeff != 0}

def poly_neg(p):
    return {degree: -coeff for degree, coeff in p.items()}

def poly_scale(p, factor):
    return {degree: coeff * factor for degree, coeff in p.items()}

def poly_mul(p, q):
    result = {}
    for deg_p, coeff_p in p.items():
        for deg_q, coeff_q in q.items():
            degree = deg_p + deg_q
            result[degree] = result.get(degree, 0) + coeff_p * coeff_q
    return {degree: coeff for degree, coeff in result.items() if coeff != 0}

