class Poly:
    """Multivariate polynomial in A and B, stored as {(a_exp, b_exp): coefficient}."""
    def __init__(self, coeffs):
        self.coeffs = {mono: c for mono, c in coeffs.items() if c}

    def is_zero(self):
        return not self.coeffs

    def __add__(self, other):
        res = dict(self.coeffs)
        for mono, c in other.coeffs.items():
            new_c = res.get(mono, 0) + c
            if new_c:
                res[mono] = new_c
            else:
                res.pop(mono, None)
        return Poly(res)

    def __neg__(self):
        return Poly({mono: -c for mono, c in self.coeffs.items()})

    def __sub__(self, other):
        return self + (-other)

    def __mul__(self, other):
        res = {}
        for (a1, b1), c1 in self.coeffs.items():
            for (a2, b2), c2 in other.coeffs.items():
                mono = (a1 + a2, b1 + b2)
                new_c = res.get(mono, 0) + c1 * c2
                if new_c:
                    res[mono] = new_c
                else:
                    res.pop(mono, None)
        return Poly(res)

    def __eq__(self, other):
        return self.coeffs == other.coeffs


