def prime_factorize(n):
    """Return prime factorization of n as a dict {prime: exponent}."""
    factors = {}
    divisor = 2
    while divisor * divisor <= n:
        while n % divisor == 0:
            factors[divisor] = factors.get(divisor, 0) + 1
            n //= divisor
        divisor += 1
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors

def sum_of_divisors(n):
    """Return the sum of all positive divisors of n."""
    factorization = prime_factorize(n)
    total = 1
    for prime, exponent in factorization.items():
        # Sum of powers of this prime: 1 + p + p^2 + ... + p^exponent
        total *= (prime ** (exponent + 1) - 1) // (prime - 1)
    return total

