def fibonacci_remainder(n, modulus):
    if n == 1:
        return 1 % modulus
    if n == 2:
        return 1 % modulus

    prev2 = 1  # F_{k-2}
    prev1 = 1  # F_{k-1}
    current = 0

    for k in range(3, n + 1):
        current = (prev1 + prev2) % modulus
        prev2, prev1 = prev1, current

    return current

