import math

def is_prime(num):
    if num < 2:
        return False
    if num % 2 == 0:
        return num == 2
    for divisor in range(3, math.isqrt(num) + 1, 2):
        if num % divisor == 0:
            return False
    return True

def prime_factorization(n):
    exponents = {}

    while n % 2 == 0:
        exponents[2] = exponents.get(2, 0) + 1
        n //= 2

    p = 3
    while p * p <= n:
        while n % p == 0:
            exponents[p] = exponents.get(p, 0) + 1
            n //= p
        p += 2

    if n > 1:
        exponents[n] = exponents.get(n, 0) + 1

    return exponents

def base_prime_representation(n):
    exponents = prime_factorization(n)

    if not exponents:
        return 0

    max_prime = max(exponents)
    digits = []

    # Build from largest prime down to 2; skip composite numbers.
    for prime in range(max_prime, 1, -1):
        if is_prime(prime):
            digits.append(str(exponents.get(prime, 0)))

    return int("".join(digits))

