def count_spacy_subsets(n):
    # dp[i] = number of spacy subsets of {1, 2, ..., i}
    dp = [0] * (n + 1)

    dp[0] = 1  # empty set
    if n >= 1:
        dp[1] = 2  # {}, {1}
    if n >= 2:
        dp[2] = 3  # {}, {1}, {2}

    for i in range(3, n + 1):
        # If i is not chosen: dp[i-1]
        # If i is chosen: i-1 and i-2 cannot be chosen, so dp[i-3]
        dp[i] = dp[i - 1] + dp[i - 3]

    return dp[n]

