import math

def divisor_count(x):
    """Return the number of positive divisors of x."""
    count = 0
    for i in range(1, int(math.isqrt(x)) + 1):
        if x % i == 0:
            count += 1
            if i * i != x:
                count += 1
    return count

def can_be_product_of_3e_plus_1(d):
    """Check whether d can be written as a product of factors of form 3e+1 (e>=1), or d=1."""
    if d == 1:
        return True
    for f in range(4, d + 1, 3):          # numbers 4, 7, 10, ...
        if d % f == 0 and can_be_product_of_3e_plus_1(d // f):
            return True
    return False

answers = set()

# Possible exponents for primes 2, 5, 11 in n.
# In 110*n^3, their divisor factors are 3a+2, 3b+2, 3c+2.
# These must divide 110 and be congruent to 2 mod 3.
possible_exponents = []
for d in range(1, 111):
    if 110 % d == 0 and d % 3 == 2:
        possible_exponents.append((d - 2) // 3)

primes = [2, 5, 11]

for a in possible_exponents:
    for b in possible_exponents:
        for c in possible_exponents:
            exponents = [a, b, c]
            p_factor = 1
            for exp in exponents:
                p_factor *= 3 * exp + 2

            if 110 % p_factor != 0:
                continue

            remaining = 110 // p_factor
            if not can_be_product_of_3e_plus_1(remaining):
                continue

            # Build n from the exponents of 2, 5, 11 and any remaining primes.
            # For simplicity, the remaining factor must be 1 here, but this loop keeps it general.
            # We enumerate possible extra primes only if needed; remaining=1 in all actual solutions.
            # Compute divisor count of 81*n^4 = 3^4 * n^4.
            # Start with the factor from 3^4.
            total = 5  # divisor factor for 3^4: exponent 4 -> 4+1

            for p, exp in zip(primes, exponents):
                # In n^4 the exponent is 4*exp, so divisor factor is 4*exp + 1.
                total *= 4 * exp + 1

            # If remaining > 1, extra primes would contribute factors 4e+1.
            # But under the given condition no such solutions exist; this branch is for completeness.
            # We can only include it if we know the extra exponents. Since remaining=1 always,
            # we just require it here.
            if remaining == 1:
                answers.add(total)

# The problem guarantees a unique value.
print(sorted(answers)[0])

