from fractions import Fraction

# Elements of Q(7^(1/3)) are represented as (a, b, c) = a + b*t + c*t^2, where t^3 = 7.

def multiply_elements(x, y):
    res = [Fraction(0), Fraction(0), Fraction(0)]
    for i in range(3):
        for j in range(3):
            if x[i] == 0 or y[j] == 0:
                continue
            coeff = x[i] * y[j]
            k = i + j
            if k == 0:
                res[0] += coeff
            elif k == 1:
                res[1] += coeff
            elif k == 2:
                res[2] += coeff
            elif k == 3:
                res[0] += coeff * 7
            else:  # k == 4
                res[1] += coeff * 7
    return tuple(res)


def solve_linear_system(aug):
    n = len(aug)
    for col in range(n):
        pivot = col
        while pivot < n and aug[pivot][col] == 0:
            pivot += 1

        aug[col], aug[pivot] = aug[pivot], aug[col]

        div = aug[col][col]
        aug[col] = [v / div for v in aug[col]]

        for row in range(n):
            if row == col:
                continue
            factor = aug[row][col]
            if factor:
                aug[row] = [a - factor * b for a, b in zip(aug[row], aug[col])]

    return [aug[i][n] for i in range(n)]


