from fractions import Fraction


def multiply_by_linear(poly, root):
    """Multiply polynomial (ascending coefficients) by (x - root)."""
    res = [Fraction(0)] * (len(poly) + 1)
    for i, c in enumerate(poly):
        res[i] += -root * c
        res[i + 1] += c
    return res


def interpolation_polynomial(xs, ys):
    """Return the unique polynomial of degree < len(xs) through the given points."""
    n = len(xs)
    poly = [Fraction(0)] * n

    for i in range(n):
        basis = [Fraction(1)]
        denom = Fraction(1)

        for j in range(n):
            if i == j:
                continue
            basis = multiply_by_linear(basis, xs[j])
            denom *= Fraction(xs[i] - xs[j])

        factor = Fraction(ys[i], denom)
        for k in range(n):
            poly[k] += basis[k] * factor

    return poly


def has_integer_coefficients(poly):
    return all(c.denominator == 1 for c in poly)


nodes = list(range(1, 9))

a = 1
while True:
    values = [a if x % 2 == 1 else -a for x in nodes]
    poly = interpolation_polynomial(nodes, values)

    if has_integer_coefficients(poly):
        print(a)
        break

    a += 1

import math

# f(x) = |2*frac(x) - 1|
def frac(x):
    return x - math.floor(x)

def fval(x):
    return abs(2.0 * frac(x) - 1.0)

# Count solutions of n*f(x*f(x)) = x for a given n.
# Equivalent to counting q in [0,n) satisfying:
#     q = n * f(q) * f(n*f(q))
# and then x = n*f(q).
def count_solutions(n):
    # We scan unit intervals of q: [k, k+1), k=0,...,n-1.
    # On each half-unit interval, f(q) is linear, so the equation
    # becomes a quadratic in q.  Count roots numerically with robust checks.
    total = 0
    eps = 1e-10

    # Breakpoints are q = k, k+0.5, k+1.
    for k in range(n):
        intervals = [
            (k, k + 0.5),
            (k + 0.5, k + 1.0),
        ]
        for a, b in intervals:
            if b > n:
                b = n
            if b - a < 1e-12:
                continue

            # On [a,b], f(q) = alpha*q + beta.
            if a >= k and a < k + 0.5:
                # f(q)=1-2(q-k)=1+2k-2q
                alpha = -2.0
                beta = 1.0 + 2.0 * k
            else:
                # f(q)=2(q-k)-1=2q-2k-1
                alpha = 2.0
                beta = -2.0 * k - 1.0

            # Let u = f(q) = alpha*q + beta.
            # Need q = n * u * f(n*u).
            # Since f is piecewise linear, f(n*u) is linear on intervals
            # where n*u lies between j and j+0.5 or j+0.5 and j+1.
            # u ranges from u_a=f(a) to u_b=f(b).
            u_a = alpha * a + beta
            u_b = alpha * b + beta
            if u_a > u_b:
                u_a, u_b = u_b, u_a
            u_a = max(u_a, 0.0)
            u_b = min(u_b, 1.0)
            if u_b <= u_a + 1e-14:
                continue

            # Breakpoints of f(n*u) occur when n*u is integer or half-integer.
            # u = j/n or u = (j+0.5)/n.
            breaks = []
            j0 = math.floor(n * u_a - 1e-12)
            j1 = math.ceil(n * u_b + 1e-12)
            for j in range(j0, j1 + 1):
                val = j / n
                if u_a - 1e-12 <= val <= u_b + 1e-12:
                    breaks.append(val)
                val = (j + 0.5) / n
                if u_a - 1e-12 <= val <= u_b + 1e-12:
                    breaks.append(val)
            breaks = sorted(set(round(x, 14) for x in breaks))
            if not breaks or breaks[0] > u_a + 1e-12:
                breaks = [u_a] + breaks
            if breaks[-1] < u_b - 1e-12:
                breaks.append(u_b)
            # Remove duplicates and sort
            uniq = []
            for x in breaks:
                if not uniq or abs(x - uniq[-1]) > 1e-10:
                    uniq.append(x)
            breaks = uniq
            if breaks[0] > u_a:
                breaks.insert(0, u_a)
            if breaks[-1] < u_b:
                breaks.append(u_b)

            # On each small u-interval, f(n*u)=gamma*u+delta.
            for i in range(len(breaks) - 1):
                u1 = breaks[i]
                u2 = breaks[i + 1]
                if u2 - u1 < 1e-12:
                    continue
                umid = (u1 + u2) / 2.0
                z = n * umid
                zz = frac(z)
                if zz < 0.5:
                    gamma = -2.0 * n
                    delta = 1.0 + 2.0 * math.floor(z)
                else:
                    gamma = 2.0 * n
                    delta = -2.0 * math.floor(z) - 1.0

                # Equation in q:
                # q = n*(alpha*q+beta)*(gamma*(alpha*q+beta)+delta)
                # Expand to A q^2 + B q + C = 0
                # Let u = alpha*q + beta.
                # RHS = n*u*(gamma*u+delta)
                #     = n*gamma*u^2 + n*delta*u
                #     = n*gamma*(alpha*q+beta)^2 + n*delta*(alpha*q+beta)
                A = n * gamma * alpha * alpha
                B = 2.0 * n * gamma * alpha * beta + n * delta * alpha - 1.0
                C = n * gamma * beta * beta + n * delta * beta

                roots = []
                if abs(A) < 1e-14:
                    if abs(B) > 1e-14:
                        roots.append(-C / B)
                else:
                    disc = B * B - 4.0 * A * C
                    if disc >= -1e-10:
                        if disc < 0:
                            disc = 0.0
                        sd = math.sqrt(disc)
                        roots.append((-B - sd) / (2.0 * A))
                        roots.append((-B + sd) / (2.0 * A))

                for r in roots:
                    # Check q is in the current q-interval and u interval matches.
                    if r < a - 1e-8 or r > b + 1e-8:
                        continue
                    rr = min(max(r, a), b)
                    uu = alpha * rr + beta
                    if uu < u1 - 1e-8 or uu > u2 + 1e-8:
                        continue
                    # Verify original equation strongly.
                    lhs = rr
                    rhs = n * fval(rr) * fval(n * fval(rr))
                    if abs(lhs - rhs) < 1e-6 * max(1.0, abs(rhs)):
                        total += 1

    # Avoid double-counting identical roots at breakpoints.
    # Since intervals are half-open in implementation, duplicates may occur;
    # use a set of rounded q values.
    # For safety, recount with a set by re-running a refined verification?
    # The above loop may count boundary roots twice.  We filter by strict
    # interior checks here by keeping unique q values.
    # To be exact, we collect roots instead of incrementing directly.
    return total

# The simple incremental counter above may double-count; use a robust collector.
def count_solutions_unique(n):
    roots = []
    eps = 1e-9
    for k in range(n):
        intervals = [(k, k + 0.5), (k + 0.5, min(k + 1.0, n))]
        for a, b in intervals:
            if b - a < 1e-12:
                continue
            if a >= k and a < k + 0.5:
                alpha, beta = -2.0, 1.0 + 2.0 * k
            else:
                alpha, beta = 2.0, -2.0 * k - 1.0

            u_a = alpha * a + beta
            u_b = alpha * b + beta
            if u_a > u_b:
                u_a, u_b = u_b, u_a
            u_a = max(u_a, 0.0)
            u_b = min(u_b, 1.0)
            if u_b - u_a < 1e-12:
                continue

            breaks = []
            j0 = math.floor(n * u_a - 1e-12)
            j1 = math.ceil(n * u_b + 1e-12)
            for j in range(j0, j1 + 1):
                for val in (j / n, (j + 0.5) / n):
                    if u_a - 1e-12 <= val <= u_b + 1e-12:
                        breaks.append(val)
            breaks.append(u_a)
            breaks.append(u_b)
            breaks.sort()
            uniq = []
            for x in breaks:
                if not uniq or abs(x - uniq[-1]) > 1e-10:
                    uniq.append(x)
            breaks = uniq

            for i in range(len(breaks) - 1):
                u1, u2 = breaks[i], breaks[i + 1]
                if u2 - u1 < 1e-12:
                    continue
                z = n * ((u1 + u2) / 2.0)
                zz = frac(z)
                if zz < 0.5:
                    gamma, delta = -2.0 * n, 1.0 + 2.0 * math.floor(z)
                else:
                    gamma, delta = 2.0 * n, -2.0 * math.floor(z) - 1.0

                A = n * gamma * alpha * alpha
                B = 2.0 * n * gamma * alpha * beta + n * delta * alpha - 1.0
                C = n * gamma * beta * beta + n * delta * beta

                cand = []
                if abs(A) < 1e-14:
                    if abs(B) > 1e-14:
                        cand.append(-C / B)
                else:
                    disc = B * B - 4.0 * A * C
                    if disc >= -1e-10:
                        if disc < 0:
                            disc = 0.0
                        sd = math.sqrt(disc)
                        cand.append((-B - sd) / (2.0 * A))
                        cand.append((-B + sd) / (2.0 * A))

                for r in cand:
                    if r < a - 1e-8 or r > b + 1e-8:
                        continue
                    rr = min(max(r, a), b)
                    uu = alpha * rr + beta
                    if uu < u1 - 1e-8 or uu > u2 + 1e-8:
                        continue
                    if abs(rr - n * fval(rr) * fval(n * fval(rr))) < 1e-6:
                        roots.append(rr)

    # Unique roots
    uniq_roots = []
    for r in sorted(roots):
        if not uniq_roots or abs(r - uniq_roots[-1]) > 1e-6:
            uniq_roots.append(r)
    return len(uniq_roots)

