from fractions import Fraction

# Polynomials are represented as lists of coefficients in ascending order:
# [a0, a1, ..., an] means a0 + a1*x + ... + an*x^n.

def poly_trim(p):
    while len(p) > 1 and p[-1] == 0:
        p.pop()
    return p

def poly_add(p, q):
    n = max(len(p), len(q))
    r = [Fraction(0)] * n
    for i in range(len(p)):
        r[i] += p[i]
    for i in range(len(q)):
        r[i] += q[i]
    return poly_trim(r)

def poly_sub(p, q):
    n = max(len(p), len(q))
    r = [Fraction(0)] * n
    for i in range(len(p)):
        r[i] += p[i]
    for i in range(len(q)):
        r[i] -= q[i]
    return poly_trim(r)

def poly_mul(p, q):
    r = [Fraction(0)] * (len(p) + len(q) - 1)
    for i, a in enumerate(p):
        for j, b in enumerate(q):
            r[i + j] += a * b
    return poly_trim(r)

def poly_scale(p, c):
    return poly_trim([a * c for a in p])

def poly_derivative(p):
    return poly_trim([p[i] * i for i in range(1, len(p))])

def poly_mod(a, b):
    # Remainder of a divided by b, using Fraction arithmetic.
    a = a[:]
    while len(a) >= len(b) and a != [Fraction(0)]:
        # leading coefficient of b must be nonzero
        factor = a[-1] / b[-1]
        shift = len(a) - len(b)
        # subtract factor * x^shift * b
        sub = [Fraction(0)] * (len(b) + shift)
        for i, coef in enumerate(b):
            sub[i + shift] = coef * factor
        a = poly_sub(a, sub)
        a = poly_trim(a)
    return a

def poly_gcd(a, b):
    while b != [Fraction(0)]:
        a, b = b, poly_mod(a, b)
    # Make gcd monic for stability
    lc = a[-1]
    return poly_scale(a, Fraction(1) / lc)

def poly_div_exact(a, b):
    # Assumes b divides a exactly.
    q = [Fraction(0)] * (len(a) - len(b) + 1)
    a = a[:]
    while len(a) >= len(b) and a != [Fraction(0)]:
        factor = a[-1] / b[-1]
        shift = len(a) - len(b)
        q[shift] = factor
        sub = [Fraction(0)] * (len(b) + shift)
        for i, coef in enumerate(b):
            sub[i + shift] = coef * factor
        a = poly_sub(a, sub)
        a = poly_trim(a)
    return poly_trim(q)

def poly_eval(p, x):
    # Horner's method
    res = Fraction(0)
    for coef in reversed(p):
        res = res * x + coef
    return res

def sturm_sequence(p):
    seq = [p, poly_derivative(p)]
    while seq[-1] != [Fraction(0)]:
        rem = poly_mod(seq[-2], seq[-1])
        # Sturm next term is the negated remainder
        seq.append(poly_scale(rem, Fraction(-1)))
    return seq[:-1]  # remove final zero polynomial

def sign_variations(seq, x):
    vals = []
    for poly in seq:
        v = poly_eval(poly, x)
        if v != 0:
            vals.append(1 if v > 0 else -1)
    count = 0
    for i in range(1, len(vals)):
        if vals[i] != vals[i - 1]:
            count += 1
    return count

# Build f(x) = x^2 - 2x
f = [Fraction(0), Fraction(-2), Fraction(1)]

# Compute f^4(x) by repeated composition: f^{n+1}(x) = f(f^n(x))
# Since f is quadratic, we can compute q = f(q) using q^2 - 2q.
q = f  # f^1
for _ in range(3):
    q = poly_sub(poly_mul(q, q), poly_scale(q, Fraction(2)))

# We need f^4(c) - 3 = 0
p = q[:]
p[0] -= Fraction(3)
p = poly_trim(p)

# Use squarefree part to count distinct roots safely.
deriv = poly_derivative(p)
g = poly_gcd(p, deriv)
if len(g) > 1:
    p_squarefree = poly_div_exact(p, g)
else:
    p_squarefree = p

# Find a bound for all real roots: Cauchy bound.
# For p(x)=a_n x^n + ... + a_0, |root| < 1 + max(|a_i|)/|a_n|.
max_abs_coeff = max(abs(coef) for coef in p_squarefree)
leading = abs(p_squarefree[-1])
M = Fraction(1) + Fraction(max_abs_coeff, leading)

sturm = sturm_sequence(p_squarefree)
variations_neg = sign_variations(sturm, -M)
variations_pos = sign_variations(sturm, M)
answer = variations_neg - variations_pos

print(answer)

