import math

def is_terminating_decimal(num, den):
    # Reduce the fraction to lowest terms
    g = math.gcd(num, den)
    den //= g

    # A terminating decimal has only prime factors 2 and 5 in the denominator
    for prime in (2, 5):
        while den % prime == 0:
            den //= prime

    return den == 1

