# 1 / ((n+1) H_n H_{n+1}) = 1 / H_n - 1 / H_{n+1}
for n in range(1, 20):
    Hn = harmonic(n)
    Hn1 = harmonic(n + 1)

    original_term = Fraction(1, n + 1) / (Hn * Hn1)
    telescoped_term = Fraction(1, 1) / Hn - Fraction(1, 1) / Hn1

    assert original_term == telescoped_term

# Therefore the infinite sum telescopes:
