from fractions import Fraction

def f(x, y):
    # Property 1: f(x, x) = x
    if x == y:
        return Fraction(x, 1)

    # Property 2: symmetry
    if x > y:
        return f(y, x)

    # Property 3: for x < y, let d = y - x.
    # Then y * f(x, d) = d * f(x, y),
    # so f(x, y) = y / d * f(x, d).
    d = y - x
    return Fraction(y, d) * f(x, d)

