def apply_swaps(assignment, swap_basils, swap_white, swap_red):
    """identical plants/lamps の入れ替えを assignment に適用する"""
    b1, b2, aloe = assignment

    if swap_basils:
        b1, b2 = b2, b1

    def swap_lamp(lamp):
        if swap_white and lamp == "W1":
            return "W2"
        if swap_white and lamp == "W2":
            return "W1"
        if swap_red and lamp == "R1":
            return "R2"
        if swap_red and lamp == "R2":
            return "R1"
        return lamp

    return (swap_lamp(b1), swap_lamp(b2), swap_lamp(aloe))

ways = set()

