    # 同じ種類の植物・ランプの入れ替えで移り合うものを同一視するため、
    # すべての対称変換を試し、その中で辞書順最小のものを代表として使う
    representatives = []
    for swap_basils in (False, True):
        for swap_white in (False, True):
            for swap_red in (False, True):
                representatives.append(
                    apply_swaps(assignment, swap_basils, swap_white, swap_red)
                )

    ways.add(min(representatives))

print(len(ways))

from math import factorial

n = 9

def generate_cycle_length_partitions(remaining, min_length=3):
    """Generate nondecreasing partitions of remaining into parts >= 3."""
    if remaining == 0:
        yield []
        return
    for first in range(min_length, remaining + 1):
        for rest in generate_cycle_length_partitions(remaining - first, first):
            yield [first] + rest

total_ways = 0

for cycle_lengths in generate_cycle_length_partitions(n):
    length_counts = {}
    for length in cycle_lengths:
        length_counts[length] = length_counts.get(length, 0) + 1

    ways = factorial(n)

    for length, count in length_counts.items():
        # Each undirected cycle of length L has (L-1)!/2 arrangements.
        # For count identical cycles, divide by count!.
        ways //= factorial(count) * ((2 * length) ** count)

    total_ways += ways

print(total_ways % 1000)

# 多項式を {次数: 係数} の辞書で表す
def scalar_multiply_poly(poly, scalar):
    """多項式の各係数をスカラー倍する"""
    return {degree: coefficient * scalar for degree, coefficient in poly.items()}

def add_polys(poly1, poly2):
    """2つの多項式を加算する"""
    result = poly1.copy()
    for degree, coefficient in poly2.items():
        result[degree] = result.get(degree, 0) + coefficient
    return result

