import math

def f(x):
    if x > -2:
        return math.ceil(1 / (x + 2))
    else:
        return math.floor(1 / (x + 2))

def is_in_range(n):
    # Every nonzero integer n is attainable:
    # choose x = 1/n - 2, so x + 2 = 1/n and f(x) = n.
    if n != 0:
        x = 1.0 / n - 2.0
        return f(x) == n

    # For n = 0:
    # If x > -2, then 1/(x+2) > 0, so ceil(...) >= 1.
    # If x < -2, then 1/(x+2) < 0, so floor(...) <= -1.
    # Therefore 0 is not in the range.
    return False

