import math

PRODUCT = -12

def positive_divisors(n):
    n = abs(n)
    divisors = []
    for d in range(1, math.isqrt(n) + 1):
        if n % d == 0:
            divisors.append(d)
            if d != n // d:
                divisors.append(n // d)
    return divisors

valid_k_values = set()

# By Vieta's formulas, if integer roots are r and s:
# r + s = k, r * s = -12
for r_abs in positive_divisors(PRODUCT):
    for r in (r_abs, -r_abs):
        s = PRODUCT // r
        k = r + s
        if k > 0:
            valid_k_values.add(k)

