def prime_factorization(n):
    factors = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors

def exponent_in_factorial(n, p):
    exponent = 0
    power = p
    while power <= n:
        exponent += n // power
        power *= p
    return exponent

