# x^2 - x + a で割った余りを考える。
# x^2 ≡ x - a を使って x^n を p(a)*x + q(a) の形に簡約する。

def poly_add(p, q):
    n = max(len(p), len(q))
    res = [0] * n
    for i in range(n):
        if i < len(p):
            res[i] += p[i]
        if i < len(q):
            res[i] += q[i]
    return res

def poly_mul(p, q):
    res = [0] * (len(p) + len(q) - 1)
    for i, ci in enumerate(p):
        for j, cj in enumerate(q):
            res[i + j] += ci * cj
    return res

def poly_eval(p, a):
    val = 0
    for c in reversed(p):
        val = val * a + c
    return val

def integer_divisors(n):
    n = abs(n)
    small = []
    large = []
    for d in range(1, int(n ** 0.5) + 1):
        if n % d == 0:
            small.append(d)
            if d * d != n:
                large.append(n // d)
    return small + large[::-1]

