        point_sub(point, edge_start),
    ) >= 0


def line_intersection(p1, p2, q1, q2):
    r = point_sub(p2, p1)
    s = point_sub(q2, q1)
    denominator = cross_vec(s, r)
    t = cross_vec(s, point_sub(q1, p1)) / denominator
    return (p1[0] + t * r[0], p1[1] + t * r[1])


def clip_polygon(subject, clip):
    output = subject

    for i in range(len(clip)):
        input_polygon = output
        output = []
        edge_start = clip[i]
        edge_end = clip[(i + 1) % len(clip)]

        for j in range(len(input_polygon)):
            current = input_polygon[j]
            nxt = input_polygon[(j + 1) % len(input_polygon)]

            current_inside = is_inside(current, edge_start, edge_end)
            next_inside = is_inside(nxt, edge_start, edge_end)

            if next_inside:
                if not current_inside:
                    output.append(
                        line_intersection(current, nxt, edge_start, edge_end)
                    )
                output.append(nxt)
            elif current_inside:
                output.append(
                    line_intersection(current, nxt, edge_start, edge_end)
                )

    return output


def polygon_area(vertices):
    total = Fraction(0)
    for i in range(len(vertices)):
        x1, y1 = vertices[i]
        x2, y2 = vertices[(i + 1) % len(vertices)]
        total += x1 * y2 - y1 * x2
    return abs(total) / 2


