import math

def count_representations(n):
    """Return the number of j >= 1 for which n is a sum of j consecutive positive odd integers."""
    count = 0
    # Since n = j * (j + 2a) with a >= 0, we have j^2 <= n.
    for j in range(1, int(math.isqrt(n)) + 1):
        if n % j == 0:
            q = n // j
            # q = j + 2a, so q >= j and q - j must be even.
            if q >= j and (q - j) % 2 == 0:
