def count_preimages_of_f0(y):
    """Return number of real x such that f0(x)=y."""
    count = 0
    # On x < -100, f0(x)=x+200, so x=y-200 is valid iff y-200 < -100 iff y < 100.
    if y < 100:
        count += 1
    # On -100 <= x <= 100, f0(x)=-x, so x=-y is valid iff -100 <= y <= 100.
    if -100 <= y <= 100:
