# 多項式を係数リストで表す: [c0, c1, c2] は c0 + c1*a + c2*a^2
def trim(poly):
    while len(poly) > 1 and poly[-1] == 0:
        poly.pop()
    return poly


def add_poly(p, q):
    n = max(len(p), len(q))
    return trim([(p[i] if i < len(p) else 0) + (q[i] if i < len(q) else 0)
                 for i in range(n)])


def mul_poly(p, q):
    r = [0] * (len(p) + len(q) - 1)
    for i, ci in enumerate(p):
        for j, cj in enumerate(q):
            r[i + j] += ci * cj
    return trim(r)


def shift_x(poly_x):
    # x を掛ける: 係数リストを次数1つ分ずらす
    return [0] + poly_x


def roots(poly):
    poly = trim(poly[:])
    if len(poly) == 2:
        # b*a + c = 0
        b, c = poly[1], poly[0]
        return [Fraction(-c, b)]
    if len(poly) == 3:
        # A*a^2 + B*a + C = 0
        A, B, C = poly[2], poly[1], poly[0]
        D = B * B - 4 * A * C
        if D < 0:
            return []
        s = math.isqrt(D)
        if s * s != D:
            return []
        return [Fraction(-B + s, 2 * A), Fraction(-B - s, 2 * A)]
    return []


