# f(x) の分子と分母（x の多項式、各係数は a の多項式）
f_num = [0, a_poly]          # a*x
f_den = [1, 1]               # x + 1

# f(f(x)) の分子 = a * f(x) の分子 = a^2*x
ff_num = [0, mul_poly(a_poly, a_poly)]

# f(f(x)) の分母 = f(x) の分子 + f(x) の分母 = (a+1)*x + 1
ff_den = add_poly(f_num, f_den)

# f(f(x)) = x より、ff_num = x * ff_den
# つまり ff_num - x * ff_den が零多項式になればよい
diff = add_poly(ff_num, shift_x([-c for c in ff_den]))

# diff の各 x 次数の係数（a の多項式）が 0 になる a を求める
candidate_roots = None
for coeff_poly in diff:
