from math import sqrt


def trim(p):
    while p and p[-1] == 0:
        p.pop()
    return p


def poly_sub(p, q):
    n = max(len(p), len(q))
    r = [0] * n
    for i in range(n):
        if i < len(p):
            r[i] += p[i]
        if i < len(q):
            r[i] -= q[i]
    return trim(r)


def poly_mul(p, q):
    if not p or not q:
        return []
    r = [0] * (len(p) + len(q) - 1)
    for i, ci in enumerate(p):
        for j, cj in enumerate(q):
            r[i + j] += ci * cj
    return trim(r)


def poly_eval(p, x):
    res = 0
    for c in reversed(p):
        res = res * x + c
    return res


def divisors(n):
    return [d for d in range(1, n + 1) if n % d == 0]


def div_linear(p, root):
    # Divide by (x - root), coefficients are in ascending order.
    n = len(p) - 1
    q = [0] * n
    q[n - 1] = p[n]
    for k in range(n - 1, 0, -1):
        q[k - 1] = p[k] + root * q[k]
    rem = p[0] + root * q[0]
    return trim(q), rem


# Points:
# (0,0,0), (1,a,0), (0,1,a), (a,0,1)
# Coplanar iff determinant of the three direction vectors is 0.
zero = []
one = [1]
a_poly = [0, 1]

matrix = [
    [one, a_poly, zero],
    [zero, one, a_poly],
    [a_poly, zero, one],
]

# det = m00*(m11*m22 - m12*m21)
#     - m01*(m10*m22 - m12*m20)
#     + m02*(m10*m21 - m11*m20)
det = poly_sub(
    poly_mul(
        matrix[0][0],
        poly_sub(
            poly_mul(matrix[1][1], matrix[2][2]),
            poly_mul(matrix[1][2], matrix[2][1]),
        ),
    ),
    poly_mul(
        matrix[0][1],
        poly_sub(
            poly_mul(matrix[1][0], matrix[2][2]),
            poly_mul(matrix[1][2], matrix[2][0]),
        ),
    ),
)
# m02 is zero, so its term is omitted.

# Find integer roots of det(a) = 0 using the rational root theorem.
constant = det[0] if det else 0
candidates = set()
if constant != 0:
    for d in divisors(abs(constant)):
        candidates.add(d)
        candidates.add(-d)
else:
    candidates.add(0)

integer_roots = []
for r in sorted(candidates):
    if poly_eval(det, r) == 0:
        integer_roots.append(r)

# Factor out all integer roots, then solve the remaining quadratic if needed.
remaining = det
all_real_roots = []

for r in integer_roots:
    if poly_eval(remaining, r) == 0:
        all_real_roots.append(r)
        remaining, rem = div_linear(remaining, r)
        # rem should be 0 for an exact root
        if rem != 0:
            raise RuntimeError("Unexpected remainder")

# remaining is now degree <= 2
if remaining:
    if len(remaining) == 2:
        # linear: c0 + c1*x = 0
        c0, c1 = remaining
        all_real_roots.append(-c0 / c1)
    elif len(remaining) == 3:
        # quadratic: c0 + c1*x + c2*x^2 = 0
        c0, c1, c2 = remaining
        disc = c1 * c1 - 4 * c0 * c2
        if disc >= 0:
            sqrt_disc = sqrt(disc)
            all_real_roots.append((-c1 + sqrt_disc) / (2 * c2))
            all_real_roots.append((-c1 - sqrt_disc) / (2 * c2))

