from fractions import Fraction
from collections import defaultdict

# A linear expression is a*l + b*m + c*n + d, stored as (a, b, c, d)
L = (1, 0, 0, 0)  # l
M = (0, 1, 0, 0)  # m
N = (0, 0, 1, 0)  # n
ZERO = (0, 0, 0, 0)

def lin_sub(p, q):
    return (p[0] - q[0], p[1] - q[1], p[2] - q[2], p[3] - q[3])

# A quadratic polynomial is stored as { (exp_l, exp_m, exp_n): coefficient }
def lin_square_to_quad(p):
    terms = [
        (p[0], (1, 0, 0)),
        (p[1], (0, 1, 0)),
        (p[2], (0, 0, 1)),
        (p[3], (0, 0, 0)),
    ]
    quad = defaultdict(int)

    for coeff, mono in terms:
        if coeff != 0:
            quad[(mono[0] * 2, mono[1] * 2, mono[2] * 2)] += coeff * coeff

    for i in range(len(terms)):
        for j in range(i + 1, len(terms)):
            ci, mi = terms[i]
            cj, mj = terms[j]
            if ci != 0 and cj != 0:
                mono = (mi[0] + mj[0], mi[1] + mj[1], mi[2] + mj[2])
                quad[mono] += 2 * ci * cj

    return dict(quad)

def quad_add(p, q):
    result = defaultdict(int, p)
    for mono, coeff in q.items():
        result[mono] += coeff
    return dict(result)

def squared_distance(P, Q):
    dx = lin_sub(Q[0], P[0])
    dy = lin_sub(Q[1], P[1])
    dz = lin_sub(Q[2], P[2])
    return quad_add(
        quad_add(lin_square_to_quad(dx), lin_square_to_quad(dy)),
        lin_square_to_quad(dz)
    )

# From the midpoint conditions:
#   B+C = (2l, 0, 0)
#   A+C = (0, 2m, 0)
#   A+B = (0, 0, 2n)
# Solving gives:
A = (-L,  M,  N)
B = ( L, -M,  N)
C = ( L,  M, -N)

AB2 = squared_distance(A, B)
AC2 = squared_distance(A, C)
BC2 = squared_distance(B, C)

numerator = quad_add(quad_add(AB2, AC2), BC2)
denominator = {(2, 0, 0): 1, (0, 2, 0): 1, (0, 0, 2): 1}

# Confirm numerator is a constant multiple of denominator
first_mono = next(iter(denominator))
ratio = Fraction(numerator[first_mono], denominator[first_mono])

for mono, coeff in denominator.items():
    assert numerator.get(mono, 0) == ratio * coeff
for mono, coeff in numerator.items():
    if coeff != 0:
        assert mono in denominator

print(int(ratio))

import math

def sum_of_n_for_quadratic_perfect_square():
    # n^2 - 19n + 99 = k^2
    # Multiply by 4: (2n - 19)^2 + 35 = (2k)^2
    # So (2k - (2n-19))(2k + (2n-19)) = 35
    target = 35
    n_values = set()

    for d in [x for x in range(1, target + 1) if target % x == 0]:
        e = target // d
        # (2k - (2n-19)) = d, (2k + (2n-19)) = e
        # Then 2k = (d + e) / 2, 2n - 19 = (e - d) / 2
        if (d + e) % 2 == 0:
            two_n_minus_19 = (e - d) // 2
            if (two_n_minus_19 + 19) % 2 == 0:
                n = (two_n_minus_19 + 19) // 2
                if n > 0:
                    k2 = n * n - 19 * n + 99
                    if math.isqrt(k2) ** 2 == k2:
                        n_values.add(n)

    return sum(n_values)

def sum_of_integer_divisors_of_12():
    # 12/n is an integer iff n is a divisor of 12
    n = 12
    total = 0
    for i in range(1, int(math.sqrt(abs(n))) + 1):
        if n % i == 0:
            total += i
            if i != n // i:
                total += n // i
            total += -i
            if -i != -(n // i):
                total += -(n // i)
    return total

first_answer = sum_of_n_for_quadratic_perfect_square()
second_answer = sum_of_integer_divisors_of_12()

print(first_answer)
print(second_answer)

