def count_numbers_with_digit_sum(digits, target_sum):
    # dp[s] = number of ways to make digit sum s using processed digits
    dp = [0] * (target_sum + 1)
    dp[0] = 1

    for _ in range(digits):
        next_dp = [0] * (target_sum + 1)
        for current_sum in range(target_sum + 1):
            if dp[current_sum] == 0:
                continue
            for digit in range(10):
                new_sum = current_sum + digit
                if new_sum <= target_sum:
                    next_dp[new_sum] += dp[current_sum]
        dp = next_dp

    return dp[target_sum]

