import math

def f(x: float) -> float:
    return -2.0 * math.sin(math.pi * x)

def g(y: float) -> float:
    """g(y) = f(f(y)) - y.  We need g(y)=0 where y=f(x)."""
    return f(f(y)) - y

def count_sign_changes_and_roots(lo: float, hi: float, n_intervals: int) -> list:
    """
    Sample g on [lo, hi], find sign-change intervals, and refine each
    root with bisection.  Roots are returned as a list of floats.
    """
    roots = []
    xs = [lo + (hi - lo) * i / n_intervals for i in range(n_intervals + 1)]
    vals = [g(x) for x in xs]

    for i in range(n_intervals):
        a, b = xs[i], xs[i + 1]
        ga, gb = vals[i], vals[i + 1]

        # Ordinary sign change: exactly one root in (a, b)
        if ga * gb < 0.0:
            left, right = a, b
            fl, fr = ga, gb
            for _ in range(80):
                mid = 0.5 * (left + right)
                fm = g(mid)
                if fl * fm <= 0.0:
                    right, fr = mid, fm
                else:
                    left, fl = mid, fm
            roots.append(0.5 * (left + right))

        # Also check endpoints, in case a root lies exactly on a sample point.
        if i > 0:
            if abs(ga) < 1e-12 and roots and abs(roots[-1] - a) > 1e-9:
                roots.append(a)
        elif abs(ga) < 1e-12:
            roots.append(a)

    # Check the right endpoint.
    if abs(vals[-1]) < 1e-12 and (not roots or abs(roots[-1] - xs[-1]) > 1e-9):
        roots.append(xs[-1])

    # Remove duplicates.
    roots.sort()
    unique = []
    for r in roots:
        if not unique or abs(r - unique[-1]) > 1e-8:
            unique.append(r)
    return unique

# H(y) = f(f(y)) - y has roots y in [-2, 2].
# Use a fine grid to catch all sign changes.
y_roots = count_sign_changes_and_roots(-2.0, 2.0, 100000)

# Count corresponding x in [-2, 2] with f(x) = y.
# f(x) = -2 sin(pi x), so sin(pi x) = -y/2.
total = 0
for y in y_roots:
    s = -y / 2.0

    if abs(s) < 1e-12:
        # sin(pi x) = 0 on [-2, 2]: x = -2, -1, 0, 1, 2
        total += 5
    elif abs(abs(s) - 1.0) < 1e-12:
        # sin(pi x) = +/-1: two half-integer solutions in two periods
        total += 2
    else:
        # For other s in (-1,1), each of the two periods has two solutions.
        total += 4

# The unique y=0 root should always be found; include it defensively.
if not any(abs(y) < 1e-12 for y in y_roots):
    total += 5

print(total)

