import itertools

def are_non_collinear(p, q, r):
    """Return True if three points form a triangle (non-collinear)."""
    v1 = (q[0] - p[0], q[1] - p[1], q[2] - p[2])
    v2 = (r[0] - p[0], r[1] - p[1], r[2] - p[2])

    # Cross product of v1 and v2; zero vector means collinear.
    cross = (
        v1[1] * v2[2] - v1[2] * v2[1],
        v1[2] * v2[0] - v1[0] * v2[2],
        v1[0] * v2[1] - v1[1] * v2[0],
    )

    return cross != (0, 0, 0)

