def vp(n, p):
    count = 0
    while n % p == 0:
        count += 1
        n //= p
    return count


def valuation_exists(req_ab, req_bc, req_cd, req_da, max_exp=6):
    for A in range(max_exp + 1):
        for B in range(max_exp + 1):
            for C in range(max_exp + 1):
                for D in range(max_exp + 1):
                    if (min(A, B) == req_ab and
                        min(B, C) == req_bc and
                        min(C, D) == req_cd and
                        min(D, A) == req_da):
                        return True
    return False


def prime_factors(n):
    factors = set()
    p = 2
    while p * p <= n:
        while n % p == 0:
            factors.add(p)
            n //= p
        p += 1
    if n > 1:
        factors.add(n)
    return factors


