import sys
from functools import lru_cache

def has_valid_coloring(m):
    # Try to color {3,...,m} so that no monochromatic a*b=c exists.
    # Color symmetry: fix color(3) = 0.
    color = {}

    def allowed_colors(c):
        # All factors are < c because a,b >= 3 and ab=c.
        allowed = {0, 1}
        a = 3
        while a * a <= c:
            if c % a == 0:
                b = c // a
                if b >= 3 and a in color and b in color:
                    ca, cb = color[a], color[b]
                    if ca == cb:
                        allowed.discard(ca)
                        if not allowed:
                            return allowed
            a += 1
        return allowed

    # Recursive backtracking, assigning numbers in increasing order.
    def dfs(x):
        if x > m:
            return True
        poss = allowed_colors(x)
        for col in tuple(poss):
            color[x] = col
            if dfs(x + 1):
                return True
            del color[x]
        return False

    color[3] = 0
    return dfs(4)


def main():
    m = 3
    while True:
        if not has_valid_coloring(m):
            print(m)
            return
        m += 1

if __name__ == "__main__":
