from itertools import product


def polynomial_value(coeffs, x):
    """Evaluate polynomial (highest degree first) using Horner's method."""
    value = 0
    for c in coeffs:
        value = value * x + c
    return value


def main():
    count = 0

    # By Cauchy's bound, every integer root r satisfies |r| < 2.
    # We test -2..2 for safety; only -1 and 0 can actually occur.
    integer_root_candidates = range(-2, 3)

    # Generate all choices of a8, a7, ..., a0
    for a8, a7, a6, a5, a4, a3, a2, a1, a0 in product([0, 1], repeat=9):
        coeffs = (1, a8, a7, a6, a5, a4, a3, a2, a1, a0)

        roots = set()
        for r in integer_root_candidates:
            if polynomial_value(coeffs, r) == 0:
                roots.add(r)

        if len(roots) == 2:
            count += 1

    print(count)


if __name__ == "__main__":
    main()

