import math

def f(x):
    if x >= -4:
        return x * x - 4
    return x + 3

def find_outer_y():
    ys = []

    # f(y) = 5, branch y >= -4:
    # y^2 - 4 = 5 => y = ±3
    for y in (3, -3):
        if y >= -4:
            ys.append(y)

    # f(y) = 5, branch y < -4:
    # y + 3 = 5 => y = 2, but 2 is not < -4
    return ys

def find_inner_x(y):
    xs = []

    # f(x) = y, branch x >= -4:
    # x^2 - 4 = y => x = ±sqrt(y + 4)
    if y + 4 >= 0:
        root = math.sqrt(y + 4)
        for x in (root, -root):
            if x >= -4:
                xs.append(x)

    # f(x) = y, branch x < -4:
    # x + 3 = y => x = y - 3
    x = y - 3
    if x < -4:
        xs.append(x)

    return xs

solutions = set()

for y in find_outer_y():
    solutions.update(find_inner_x(y))

print(len(solutions))

