def count_distinct_prime_factors(n):
    count = 0
    remaining = n
    divisor = 3

    while divisor * divisor <= remaining:
        if remaining % divisor == 0:
            count += 1
            while remaining % divisor == 0:
                remaining //= divisor
        divisor += 2

    if remaining > 1:
        count += 1

    return count

